const providerBrowse={audience:'learners'};
const learnerNeeds=[];
all.push(...learnerNeeds);
const priorExplore=explore,priorResults=results,priorDetail=detail,priorEnquire=enquire;
function providerAudience(a){if(!['learners','institutions'].includes(a))return;providerBrowse.audience=a;state.query='';state.mode='All modes';state.category='All';navigate('explore')}
explore=function(){if(state.role!=='training')return priorExplore();const learners=providerBrowse.audience==='learners';$('#main').innerHTML=intro('TRAINING PROVIDER OPPORTUNITIES',learners?'Connect your courses with learners.':'Bring your expertise to institutions.',learners?'Explore learning requirements from adult learners and parent-managed accounts.':'Discover institutional training briefs and partnership opportunities.','Published requirements')+`<div class="tabs" role="group" aria-label="Opportunity audience"><button class="chip ${learners?'active':''}" onclick="providerAudience('learners')" aria-pressed="${learners}">Individual Learners</button><button class="chip ${!learners?'active':''}" onclick="providerAudience('institutions')" aria-pressed="${!learners}">Institutional Opportunities</button></div><form class="searchbar" id="search-form"><input id="query" aria-label="Search skills or location" placeholder="Search skills, programme needs or location" value="${esc(state.query)}"><select id="mode" aria-label="Delivery mode">${['All modes','Online','In person','Hybrid'].map(m=>`<option ${m===state.mode?'selected':''}>${m}</option>`).join('')}</select><button class="btn">Search ↗</button></form><div class="feature-band"><div><span class="tiny">${learners?'INDIVIDUAL ENROLMENT':'INSTITUTIONAL PARTNERSHIPS'}</span><h2>${learners?'Offer learning that fits their goals.':'Turn expertise into partnerships.'}</h2><p>${learners?'Match your courses to subject, skill, timing and budget preferences.':'Respond to workshops, staff development and student training needs.'}</p></div><button class="btn lime" onclick="${learners?'openProviderCourses()':"billing.audience='training';navigate('plans')"}">${learners?'Manage my courses':'Explore business plans'} ↗</button></div><div class="section-top"><h2>${learners?'Individual learning requirements':'Institutional requirements'}</h2><span id="result-count" class="count"></span></div><div class="cards" id="results"></div><p class="bottom-note">Only published learner requirements will appear here. Learner contact details are shared only after adult or parent consent.</p>`;$('#search-form').onsubmit=e=>{e.preventDefault();state.query=$('#query').value;state.mode=$('#mode').value;results()};results()};
results=function(){if(state.role!=='training')return priorResults();const q=state.query.toLowerCase().trim(),src=providerBrowse.audience==='learners'?learnerNeeds:business;const items=src.filter(i=>(state.mode==='All modes'||i.mode===state.mode)&&(!q||[i.name,i.title,i.subtitle,i.desc,i.location,...i.tags].join(' ').toLowerCase().includes(q)));$('#result-count').textContent=items.length+' results';$('#results').innerHTML=items.length?items.map(card).join(''):'<div class="empty"><h3>No matching requirements</h3><p class="muted">Try a different skill or delivery mode.</p><button class="btn light" onclick="resetSearch()">Clear filters</button></div>'};
detail=function(id){if(id<400)return priorDetail(id);const i=learnerNeeds.find(x=>x.id===id);if(!i)return;modal(`<span class="eyebrow">LEARNING REQUIREMENT</span><h2>${i.title}</h2><p class="muted">${i.subtitle}</p><div class="tags">${i.tags.map(t=>`<span>${t}</span>`).join('')}</div><p class="muted">${i.details}</p><div class="panel"><strong>${i.price}</strong><p class="muted">${i.location} · ${i.mode}</p></div><p class="bottom-note">No personal contact information is available. Real connections will require acceptance from the adult learner or parent.</p><div class="dialog-actions"><button class="btn" onclick="enquire(${id})">Offer a relevant course</button><button class="btn outline" onclick="save(${id})">Shortlist requirement</button></div>`)};
enquire=function(id){if(id<400)return priorEnquire(id);const i=learnerNeeds.find(x=>x.id===id);if(!i)return;$('#modal').close();modal(`<span class="eyebrow">COURSE OFFER</span><h2>${i.title}</h2><p class="muted">Propose a programme to the adult learner or parent. This offer is currently saved in your session until messaging is connected.</p><form id="learner-offer"><div class="fields"><label class="full">Course / programme name<input name="course" required maxlength="150"></label><label class="full">How does it meet this requirement?<textarea name="message" required maxlength="1500"></textarea></label><label>Fee and billing period<input name="fee" required maxlength="100" placeholder="₹2,000 / month"></label><label>Delivery mode<select name="mode"><option>Online</option><option>In person</option><option>Hybrid</option></select></label></div><button class="btn">Save course offer</button></form>`);$('#learner-offer').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.enquiries.push({role:state.role,target:i.name,title:i.title,message:d.get('course')+' — '+d.get('message')+' · '+d.get('fee'),mode:d.get('mode')});$('#modal').close();navigate('enquiries');toast('Course offer saved for this session.')}};
function openProviderCourses(){registration.step=steps().findIndex(x=>x.id==='courses');navigate('profile')}
const oldSide=side;side=function(page){oldSide(page);if(state.role==='training'){const a=$('#side-nav a[href="#explore"]');if(a)a.innerHTML='<span class="symbol">⌕</span>Learners & institutions'}};
const oldProviderWorkspace=workspace;workspace=function(){oldProviderWorkspace();if(state.role==='training')$('#main').insertAdjacentHTML('afterbegin',`<section class="panel"><h2>Two ways to grow your training business</h2><div class="workspace-links" style="margin-top:18px"><button class="btn" onclick="providerAudience('learners')">Find Individual Learners</button><button class="btn light" onclick="providerAudience('institutions')">Institutional Opportunities</button><button class="btn outline" onclick="openProviderCourses()">Manage Courses</button></div></section>`)};
if(state.role==='training')render();
